package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.server.level.*;import net.minecraft.network.chat.Component;import net.minecraft.core.BlockPos;import java.util.*;
public final class DefenseLinkTool extends Item{
 public DefenseLinkTool(Properties p){super(p);}
 @Override public InteractionResult useOn(UseOnContext c){var state=c.getLevel().getBlockState(c.getClickedPos());if(state.getBlock()instanceof AdcBlock block)return block.interact(state,c.getLevel(),c.getClickedPos(),c.getPlayer(),c.getHand());if(!(state.getBlock()instanceof DefenseBlock))return InteractionResult.PASS;if(c.getLevel().isClientSide)return InteractionResult.SUCCESS;var b=DefenseBlock.main(c.getLevel(),c.getClickedPos(),state);if(b==null||!(c.getPlayer()instanceof ServerPlayer p)||p.distanceToSqr(c.getClickLocation())>36||!c.getLevel().mayInteract(p,c.getClickedPos()))return InteractionResult.FAIL;var data=DefenseData.get(p.serverLevel());var site=data.site(b.id);if(site==null)return InteractionResult.FAIL;if(!DefenseData.allowed(p.serverLevel(),site.owner,site.name,p))return reply(p,"DENIED");if(p.isShiftKeyDown()){if(b.kind()==0){data.unlink(b.id);b.changed();return reply(p,"UNLINKED");}var n=DefenseItem.data(c.getItemInHand());n.remove("Radar");DefenseItem.data(c.getItemInHand(),n);return reply(p,"CLEARED");}if(b.kind()==1){var n=DefenseItem.data(c.getItemInHand());n.putUUID("Radar",b.id);n.putLong("RadarRoot",b.getBlockPos().asLong());n.putString("Dimension",p.level().dimension().location().toString());DefenseItem.data(c.getItemInHand(),n);return reply(p,"RADAR_SELECTED");}return link(p,c.getItemInHand(),b.id);}
 public static InteractionResult link(ServerPlayer p,ItemStack stack,UUID launcher){var n=DefenseItem.data(stack);if(!n.hasUUID("Radar"))return reply(p,"SELECT_RADAR");if(!n.getString("Dimension").equals(p.level().dimension().location().toString()))return reply(p,"DIMENSION");return reply(p,DefenseData.get(p.serverLevel()).link(p.serverLevel(),n.getUUID("Radar"),launcher,p));}
 static InteractionResult reply(ServerPlayer p,String key){p.displayClientMessage(Component.translatable("defense.status."+key),true);return InteractionResult.CONSUME;}
 @Override public void appendHoverText(ItemStack s,Item.TooltipContext l,List<Component>text,TooltipFlag flag){text.add(Component.translatable("defense.link.description"));}
}
